def standardize_rope_params(config, rope_theta=None):
    """
    Helper to standardize the config's rope params field by ensuring the params are defined for each
    later type. For old model the fn will duplicate a single rope param in each layer type (backward compatibility)
    """
    rope_parameters = getattr(config, "rope_parameters", None)
    layer_types = getattr(config, "layer_types", None)

    if rope_theta is None:
        rope_theta = getattr(config, "rope_theta", None)

    if not isinstance(rope_parameters, dict):
        if rope_parameters is None:
            rope_parameters = {"rope_type": "default", "rope_theta": rope_theta}
        config.rope_parameters = rope_parameters
    elif layer_types is not None:
        # Multi-layer config: check if in new format (per-layer-type keys)
        is_field_in_new_format = any(
            layer_type in rope_parameters for layer_type in layer_types
        )
        if not is_field_in_new_format:
            # Old format: duplicate rope_parameters for each layer type
            rope_parameters_per_layer_type = {}
            for layer_type in layer_types:
                curr_rope_type = rope_parameters.get("rope_type", "default")
                rope_parameters_per_layer_type[layer_type] = {
                    "rope_type": curr_rope_type,
                    "rope_theta": rope_parameters.get("rope_theta", rope_theta),
                }
                rope_parameters_per_layer_type[layer_type].update(rope_parameters)
            rope_parameters = rope_parameters_per_layer_type
        config.rope_parameters = rope_parameters
    else:
        # Single-layer dict: ensure required keys
        if "rope_type" not in rope_parameters:
            rope_parameters["rope_type"] = "default"
        if "rope_theta" not in rope_parameters:
            rope_parameters["rope_theta"] = rope_theta
        config.rope_parameters = rope_parameters


